MIX = {"still": -3, "tender": -3, "grief": -3, "calm": -1.5, "wonder": -1.5, "dread": -0.5, "awe": 1, "joy": 1, "chase": 1.5, "wrath": 1.5}

def build(n):
    e = EP[n]
    mood = "still"   # dynamics: a line with no mixDb of its own takes one from its music mood (the mix needs LRA ≥ 4 LU)
    for l in e["lines"]:
        mood = l.get("music", mood)
        if l.get("voice") is not False and "mixDb" not in l and l["id"] != "hook": l["mixDb"] = MIX.get(mood, 0)
    strings = {"seriesTitle": "Mahabharatam", "seriesSubtitle": "As Vyasa Told It", "episodeLabel": f"Episode {n}", "episodeTitle": TITLES[n], "episodeSeparator": " · ", "previouslyLabel": "Previously", "nextLabel": "Next",
               "traditionNote": "As tradition tells it", "prevEpisodeLabel": f"Episode {n - 1}", "prevEpisodeTitle": TITLES[n - 1], "recapLine": e["recap"], "nextEpisodeLabel": f"Episode {n + 1}", "nextTitle": TITLES[n + 1],
               "sourceLine": f"{e['ref']} · {SRC}", "madeLine": MADE}
    strings.update(e.get("strings_extra", {}))
    return {
        "lang": "en", "fonts": {"caption": "'EB Garamond'", "display": "'Cinzel'"},
        "timing": {"wordsPerSecond": 2.4, "voiceGap": 0.35, "voiceLead": 0.12, "tail": 0.25},
        "voice": {"pauses": {"ellipsis": 420, "dash": 280, "comma": 80, "stop": 250}, "note": "speaker → script/cast.json (voice, speed, pitch). Per line: speed (× the speaker's), pre/post (ms of silence before/after the voice), say (what is spoken, if not `text`), estVoice (s: the predicted voice length, tools/estimate.py; replaced by the real voice once tools/voice.py has run)."},
        "captionBand": {"y": 1400, "kinetic": True},
        "episode": n,
        "source": e["source"],
        "structure": "As from episode 41 (script/ARC-41-50.md, script/ARC-51-60.md): COLD OPEN (≤ 8 words; the hook style rotates and never repeats the episode before; no episode of this batch opens on fire) → title (hook post) → STORY from ≈ 4.5 s with the UNVOICED recap band → the episode stands alone (every name has an identifier in \"names\", shown as a plaque) → one question closed (loop.answeredBy), the previous one answered by 15 s (loop.prevAnsweredBy) → turn at 40–60 % after a real silence, a second silence where the story allows → one face close-up with a change of emotion → one signature shot → the cliffhanger with the source line → a ≤ 1.2 s NEXT › band that dissolves into frame 1. Per line: pal (the colour script: no hue for more than two lines), cam (≥ 4 distinct moves), tr (transitions born from the medium), amb / foley / music (three sound layers; ambLead / ambLag = J- and L-cuts). Gate: tools/gate.mjs.",
        "hookStyle": e["hookStyle"],
        "names": e["names"],
        "loop": e["loop"],
        "strings": strings,
        "lines": e["lines"],
    }

if __name__ == "__main__":
    only = [int(x) for x in sys.argv[1:]] or sorted(EP)
    for n in only:
        p = os.path.join(ROOT, "script", f"ep{n:02d}.en.json")
        json.dump(build(n), open(p, "w"), indent=2, ensure_ascii=False)
        open(p, "a").write("\n")
        words = sum(len(l["text"].split()) for l in EP[n]["lines"] if l.get("voice") is not False)
        print(f"ep{n}: {len(EP[n]['lines'])} lines, {words} words")
